$('#yr').textContent=now.getFullYear();
addEventListener('scroll',()=>$('#nav').classList.toggle('sc',scrollY>20),{passive:true});
/* hero video */
(()=>{const v=document.createElement('video');v.muted=true;v.defaultMuted=true;v.loop=true;v.playsInline=true;v.autoplay=true;v.setAttribute('playsinline','');v.setAttribute('muted','');v.preload='auto';v.poster=img(im[0]);v.setAttribute('aria-hidden','true');v.addEventListener('playing',()=>$('#bgv').classList.add('on'),{once:true});v.src=th.vid;$('#bgv').appendChild(v);const p=v.play();p&&p.catch(()=>{})})();
$$('.qa button').forEach(b=>b.onclick=()=>{const q=b.parentElement,on=!q.classList.contains('on');$$('.qa').forEach(x=>{x.classList.remove('on');x.querySelector('button').setAttribute('aria-expanded','false')});if(on){q.classList.add('on');b.setAttribute('aria-expanded','true')}});
const A={g:'',l:''};let step=0;const qs=$$('.qs'),bars=$$('.qbar i'),back=$('.qnav .back'),go=$('#qgo');
const upd=()=>{const nm=$('#qn').value.trim();go.href=wa(hello+'Je veux réserver une séance d’essai.\n• Objectif : '+A.g+'\n• Niveau : '+A.l+'\n• Moment : '+$('#qd').value+(nm?'\n• Prénom : '+nm:''))};
const show=n=>{step=n;qs.forEach((q,i)=>q.classList.toggle('on',i===n));bars.forEach((b,i)=>b.classList.toggle('on',i<=n));back.hidden=n===0;go.style.display=n===2?'inline-flex':'none';upd()};
$$('.chips').forEach(c=>c.onclick=e=>{const b=e.target.closest('.chip');if(!b)return;$$('.chip',c).forEach(x=>x.classList.remove('on'));b.classList.add('on');A[c.dataset.k]=b.textContent;setTimeout(()=>show(step+1),240)});
back.onclick=()=>show(Math.max(0,step-1));['#qd','#qn'].forEach(s=>$(s).addEventListener('input',upd));
/* FZ: body lab */
(()=>{let sx='m';const g=id=>document.getElementById(id);const f=n=>Math.round(n).toLocaleString('fr-FR');
const calc=()=>{const a=+g('lag').value,h=+g('lht').value,w=+g('lwt').value,ac=+g('lac').value,go=+g('lgo').value;
['lag','lht','lwt'].forEach(k=>{const e=g(k);e.style.setProperty('--v',((e.value-e.min)/(e.max-e.min)*100)+'%')});g('vag').textContent=a;g('vht').textContent=h;g('vwt').textContent=w;
const bmi=w/((h/100)**2),bmr=10*w+6.25*h-5*a+(sx==='m'?5:-161),tdee=bmr*ac,tg=Math.max(1200,tdee+go),pr=w*(go>0?2:1.8);
const cat=bmi<18.5?'Sous le poids idéal':bmi<25?'Poids idéal':bmi<30?'Léger surpoids':'Surpoids';
g('lbmi').innerHTML=bmi.toFixed(1).replace('.',',')+'<small>IMC</small>';g('lcat').textContent=cat;g('lring').style.setProperty('--p',Math.min(100,Math.max(8,(bmi-14)/(40-14)*100)));
g('lk1').textContent=f(tdee);g('lk2').textContent=f(tg);g('lk3').textContent=f(pr);
const gl=g('lgo').selectedOptions[0].text;g('lgo2').href=wa(hello+'Voici mon profil Body Lab :\n• '+(sx==='m'?'Homme':'Femme')+', '+a+' ans, '+h+' cm, '+w+' kg\n• IMC : '+bmi.toFixed(1)+' ('+cat+')\n• Objectif : '+gl+' (≈ '+f(tg)+' kcal/j)\nPouvez-vous me proposer un programme et une séance d’essai ?')};
$$('#lsx button').forEach(b=>b.onclick=()=>{$$('#lsx button').forEach(x=>x.classList.remove('on'));b.classList.add('on');sx=b.dataset.v;if(sx==='f'&&+g('lwt').value===78){g('lwt').value=62;g('lht').value=164}calc()});
['lag','lht','lwt','lac','lgo'].forEach(k=>g(k).addEventListener('input',calc));calc()})();
/* FZ: particles, cursor glow, tilt */
(()=>{const rm=matchMedia('(prefers-reduced-motion:reduce)').matches;const c=document.getElementById('fzp');if(c&&!rm){const x=c.getContext('2d');const cs=getComputedStyle(document.documentElement);const col=cs.getPropertyValue('--ac').trim()||'#22e6ff';let W,H,P=[],vis=true;const N=innerWidth<700?28:64;
const rs=()=>{const r=c.getBoundingClientRect();W=c.width=r.width*devicePixelRatio;H=c.height=r.height*devicePixelRatio};rs();addEventListener('resize',rs);
for(let i=0;i<N;i++)P.push({x:Math.random(),y:Math.random(),vx:(Math.random()-.5)*.0006,vy:(Math.random()-.5)*.0006});
new IntersectionObserver(e=>vis=e[0].isIntersecting).observe(c);
const hex=h=>{h=h.replace('#','');const n=parseInt(h.length===3?h.split('').map(z=>z+z).join(''):h,16);return[(n>>16)&255,(n>>8)&255,n&255]};const [r,gg,b]=hex(col);
const tick=()=>{if(vis){x.clearRect(0,0,W,H);for(const p of P){p.x=(p.x+p.vx+1)%1;p.y=(p.y+p.vy+1)%1}
for(let i=0;i<N;i++){const a=P[i];x.fillStyle=`rgba(${r},${gg},${b},.9)`;x.beginPath();x.arc(a.x*W,a.y*H,1.6*devicePixelRatio,0,7);x.fill();for(let j=i+1;j<N;j++){const q=P[j],dx=(a.x-q.x)*W,dy=(a.y-q.y)*H,d=Math.hypot(dx,dy),m=150*devicePixelRatio;if(d<m){x.strokeStyle=`rgba(${r},${gg},${b},${(1-d/m)*.35})`;x.lineWidth=devicePixelRatio;x.beginPath();x.moveTo(a.x*W,a.y*H);x.lineTo(q.x*W,q.y*H);x.stroke()}}}}requestAnimationFrame(tick)};tick()}
if(matchMedia('(hover:hover) and (pointer:fine)').matches&&!rm){const cu=document.createElement('div');cu.className='cur';document.body.appendChild(cu);addEventListener('pointermove',e=>{cu.style.opacity=1;cu.style.transform=`translate(${e.clientX}px,${e.clientY}px)`},{passive:true});
$$('.ac,.fc,.rc,.hud').forEach(el=>{el.style.transition=(el.style.transition?el.style.transition+',':'')+'transform .25s ease-out';el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect(),px=(e.clientX-r.left)/r.width-.5,py=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(900px) rotateY(${px*7}deg) rotateX(${-py*7}deg)`+(el.classList.contains('hud')?' translateY(-38%)':'')});el.addEventListener('pointerleave',()=>el.style.transform=el.classList.contains('hud')?'translateY(-38%)':'')})}})();

