$$('.sp').forEach(h=>{const walk=n=>{[...n.childNodes].forEach(c=>{if(c.nodeType===3){const f=document.createDocumentFragment();c.textContent.split(/([ \t\n]+)/).forEach(t=>{if(!t)return;if(/^[ \t\n]+$/.test(t)){f.appendChild(document.createTextNode(t));return}const w=document.createElement('span');w.className='w';const s=document.createElement('span');s.textContent=t;w.appendChild(s);f.appendChild(w)});c.replaceWith(f)}else if(c.nodeType===1)walk(c)})};walk(h)});
